const uint16 dt_cn16_table_size = (uint16)(sizeof(dt_cn16_table) / sizeof(dt_cn16_table[0]));

const uint8 *dt_cn_font_get (uint8 code_high, uint8 code_low)
{
    uint16 code = (uint16)(((uint16)code_high << 8) | code_low);
    uint16 i = 0;

    for(i = 0; i < dt_cn16_table_size; i++)
    {
        if(code == dt_cn16_table[i].code)
        {
            return dt_cn16_table[i].data;
        }
    }
    return (const uint8 *)0;
}
